//! Text against the pygame 2.6.1 / SDL_ttf 2.20.1 goldens in `golden/text`
//! (generated by `tools/pygame-golden/text/gen_text.py`), on the bundled
//! JetBrains Mono (SIL OFL 1.1) and its baked atlas in `fixtures/atlas`.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

use banquo_canvas::text::classify::{self, DiffClass, KnownDifference, Verdict};
use banquo_canvas::text::{self, FontFace, OverlapRule, TextError};
use banquo_canvas::{Rgba8, Surface};
use serde::Deserialize;
use sha2::{Digest, Sha256};

const FONT_SHA256: &str = "a0bf60ef0f83c5ed4d7a75d45838548b1f6873372dfac88f71804491898d138f";
const ATLAS: &str = "fixtures/atlas/jetbrains-mono-regular";
const FULL_SIZES: [u32; 4] = [14, 18, 26, 34];
const ZERO_WIDTH: &str = "zero_width_error";

fn tests_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests")
}

fn read(rel: &str) -> Vec<u8> {
    let path = tests_dir().join(rel);
    fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn sha256_hex(data: &[u8]) -> String {
    Sha256::digest(data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn font_bytes() -> Vec<u8> {
    read("fixtures/fonts/JetBrainsMono-Regular.ttf")
}

fn face() -> &'static FontFace {
    static FACE: OnceLock<FontFace> = OnceLock::new();
    FACE.get_or_init(|| {
        FontFace::from_dir(font_bytes(), &tests_dir().join(ATLAS)).expect("fixture atlas loads")
    })
}

fn atlas_pages() -> BTreeMap<String, Vec<u8>> {
    (10..40)
        .map(|s| {
            let name = format!("atlas-{s}.png");
            let bytes = read(&format!("{ATLAS}/{name}"));
            (name, bytes)
        })
        .collect()
}

#[derive(Deserialize)]
struct Entry {
    size: u32,
    index: usize,
    category: String,
    text: String,
    render: String,
}

#[derive(Deserialize)]
struct Measured {
    size: u32,
    index: usize,
    w: i32,
    h: i32,
}

#[derive(Deserialize)]
struct Manifest {
    header: BTreeMap<String, serde_json::Value>,
    files: BTreeMap<String, String>,
    fixtures: BTreeMap<String, String>,
}

fn corpus() -> Vec<Entry> {
    serde_json::from_slice(&read("golden/text/corpus.json")).expect("corpus.json")
}

fn measured() -> BTreeMap<(u32, usize), (i32, i32)> {
    let rows: Vec<Measured> =
        serde_json::from_slice(&read("golden/text/sizes.json")).expect("sizes.json");
    rows.into_iter()
        .map(|m| ((m.size, m.index), (m.w, m.h)))
        .collect()
}

fn manifest() -> Manifest {
    serde_json::from_slice(&read("golden/text/MANIFEST.json")).expect("MANIFEST.json")
}

fn colour() -> Rgba8 {
    let c = &manifest().header["colour"];
    let ch = |i: usize| c[i].as_u64().expect("colour") as u8;
    Rgba8::rgb(ch(0), ch(1), ch(2))
}

fn known_differences() -> BTreeMap<(u32, usize), KnownDifference> {
    let list: Vec<KnownDifference> =
        serde_json::from_slice(&read("golden/text/approved_differences.json"))
            .expect("approved_differences.json: a list of {size, index, class, sha256}");
    let mut out = BTreeMap::new();
    for k in list {
        let key = (k.size, k.index);
        assert!(out.insert(key, k).is_none(), "duplicate entry {key:?}");
    }
    out
}

/// pygame's render of entry (size, index): an 8-bit RGBA PNG.
fn pygame_render(size: u32, index: usize) -> Surface {
    let bytes = read(&format!("golden/text/{size}/{index}.png"));
    let decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    let mut reader = decoder.read_info().expect("png header");
    let mut buf = vec![0; reader.output_buffer_size().expect("png size")];
    let info = reader.next_frame(&mut buf).expect("png frame");
    assert_eq!(info.bit_depth, png::BitDepth::Eight);
    assert_eq!(info.color_type, png::ColorType::Rgba);
    let mut s = Surface::new(info.width, info.height, true);
    for (i, &[r, g, b, a]) in buf.as_chunks::<4>().0.iter().enumerate() {
        if i >= (info.width * info.height) as usize {
            break;
        }
        let (x, y) = (
            (i as u32 % info.width) as i32,
            (i as u32 / info.width) as i32,
        );
        s.set(x, y, Rgba8::new(r, g, b, a));
    }
    s
}

/// The digest that pins a Rust render in `approved_differences.json`.
fn output_sha256(s: &Surface) -> String {
    sha256_hex(&classify::output_digest_input(s))
}

// --- E1: fixtures ---------------------------------------------------------

#[test]
fn fixture_font_is_the_pinned_ofl_font() {
    assert_eq!(sha256_hex(&font_bytes()), FONT_SHA256);
    let ofl = String::from_utf8(read("fixtures/fonts/OFL.txt")).expect("OFL.txt");
    assert!(ofl.contains("SIL OPEN FONT LICENSE Version 1.1"));
    assert_eq!(face().atlas_font_sha256(), FONT_SHA256);
}

#[test]
fn atlas_is_format_2_with_30_sizes_and_full_glyph_sets() {
    let doc: serde_json::Value =
        serde_json::from_slice(&read(&format!("{ATLAS}/atlas.json"))).expect("atlas.json");
    assert_eq!(doc["format"], 2);
    let keys: BTreeSet<u32> = doc["sizes"]
        .as_object()
        .expect("sizes")
        .keys()
        .map(|k| k.parse().expect("size key"))
        .collect();
    assert_eq!(keys, (10..40).collect::<BTreeSet<u32>>());
    let glyph_count = doc["glyph_count"].as_u64().expect("glyph_count") as u32;
    assert_eq!(glyph_count, 1743);
    let face = face();
    for size in FULL_SIZES {
        assert_eq!(face.glyph_count(size), glyph_count as usize, "size {size}");
        assert!(
            (0..glyph_count).all(|g| face.has_glyph(size, g)),
            "size {size}"
        );
    }
    // Every subset character is baked at every size.
    for size in 10..40 {
        for ch in doc["tile_chars"].as_array().expect("tile_chars") {
            let ids = text::shape(face, ch.as_str().expect("char"));
            assert!(ids.iter().all(|&g| face.has_glyph(size, g)), "size {size}");
        }
        assert!(face.has_glyph(size, 0), ".notdef at {size}");
    }
}

#[test]
fn golden_manifest_lists_every_generated_file() {
    let m = manifest();
    assert!(!m.files.contains_key("approved_differences.json"));
    assert!(!m.files.contains_key("MANIFEST.json"));
    for (rel, sum) in &m.files {
        assert_eq!(
            &sha256_hex(&read(&format!("golden/text/{rel}"))),
            sum,
            "{rel}"
        );
    }
    for (rel, sum) in &m.fixtures {
        assert_eq!(&sha256_hex(&read(&format!("fixtures/{rel}"))), sum, "{rel}");
    }
    let pngs = corpus().iter().filter(|e| e.render != ZERO_WIDTH).count();
    let listed = m.files.keys().filter(|k| k.ends_with(".png")).count();
    assert_eq!(listed, pngs);
    assert_eq!(m.fixtures.len(), 31);
}

// --- E2: shaping ----------------------------------------------------------

#[cfg(feature = "shaping")]
#[test]
fn shape_sets_ltr_and_sdl_ttf_script() {
    let buffer = text::shaping_buffer("->");
    assert_eq!(buffer.direction(), text::ShapeDirection::LeftToRight);
    assert_eq!(text::DIRECTION, text::ShapeDirection::LeftToRight);
    let script = buffer.script().expect("script is set");
    assert_eq!(script, text::SCRIPT);
    assert_eq!(script.tag().to_be_bytes(), *b"Zzzz");
    assert!(buffer.language().is_none(), "language stays unset");
    assert!(
        text::USER_FEATURES.is_empty(),
        "SDL_ttf passes no user features"
    );

    let face = face();
    let arrow = text::shape(face, "->");
    let mut split = text::shape(face, "-");
    split.extend(text::shape(face, ">"));
    assert_eq!(arrow.len(), 2);
    assert_ne!(arrow, split, "calt changes the glyphs of \"->\"");
    assert!(text::shape(face, "").is_empty());
    assert_eq!(text::shape(face, "\u{4e2d}"), vec![0], ".notdef");
}

// --- E3: measure ----------------------------------------------------------

#[test]
fn measure_matches_pygame_font_size() {
    let face = face();
    let sizes = measured();
    let mut mismatches = Vec::new();
    let corpus = corpus();
    for e in &corpus {
        let want = sizes[&(e.size, e.index)];
        let got = text::measure(face, e.size, &e.text);
        if got != want {
            mismatches.push(format!(
                "size={} index={} got={got:?} want={want:?}",
                e.size, e.index
            ));
        }
    }
    println!(
        "measure {} entries, {} mismatches",
        corpus.len(),
        mismatches.len()
    );
    assert!(mismatches.is_empty(), "{mismatches:#?}");

    for (size, advance, line_height) in [(14, 8, 19), (18, 11, 24), (26, 16, 35), (34, 20, 45)] {
        assert_eq!(face.advance(size), Some(advance));
        assert_eq!(face.line_height(size), Some(line_height));
        assert_eq!(text::measure(face, size, ""), (0, line_height));
        for n in 1..=12 {
            let s = "Mx.".repeat(n);
            assert_eq!(
                text::measure(face, size, &s),
                (advance * 3 * n as i32, line_height)
            );
        }
    }
}

// --- E4: render -----------------------------------------------------------

struct Outcome {
    size: u32,
    index: usize,
    verdict: Verdict,
    sha256: String,
    pixels: usize,
    pygame_refused: bool,
}

/// Every corpus entry rendered under `rule` and judged against pygame and
/// `known`.
fn judge(
    rule: Option<OverlapRule>,
    known: &BTreeMap<(u32, usize), KnownDifference>,
) -> Vec<Outcome> {
    let face = face();
    let colour = colour();
    let sizes = measured();
    corpus()
        .iter()
        .map(|e| {
            let got = match rule {
                Some(r) => text::render_with_rule(face, e.size, &e.text, colour, r),
                None => text::render(face, e.size, &e.text, colour),
            };
            let refused = e.render == ZERO_WIDTH;
            let (exact, pixels) = if refused {
                (false, 0)
            } else {
                let want = pygame_render(e.size, e.index);
                (got == want, classify::differing_pixels(&got, &want))
            };
            let sha = output_sha256(&got);
            let pygame_w = sizes[&(e.size, e.index)].0;
            let verdict = classify::verdict(
                exact,
                || classify::classify(face, &e.text, pygame_w, got.width() as i32),
                known.get(&(e.size, e.index)),
                &sha,
            );
            Outcome {
                size: e.size,
                index: e.index,
                verdict,
                sha256: sha,
                pixels,
                pygame_refused: refused,
            }
        })
        .collect()
}

fn report(outcomes: &[Outcome]) -> Vec<String> {
    let mut failures = Vec::new();
    for size in 10..40u32 {
        let of_size: Vec<&Outcome> = outcomes.iter().filter(|o| o.size == size).collect();
        let n = of_size.len();
        let exact = of_size
            .iter()
            .filter(|o| o.verdict == Verdict::Exact)
            .count();
        let pinned = of_size
            .iter()
            .filter(|o| o.verdict == Verdict::Pinned)
            .count();
        if exact == n {
            println!("text {size} {n}/{n} exact");
        } else {
            println!("text {size} {exact}/{n} exact, {pinned} pinned");
        }
        for o in of_size {
            match &o.verdict {
                Verdict::Exact | Verdict::Pinned => {}
                Verdict::Unpinned(class) => {
                    let line = format!(
                        "DIFF size={} index={} class={} sha256={} pixels={}{}",
                        o.size,
                        o.index,
                        class.as_str(),
                        o.sha256,
                        o.pixels,
                        if o.pygame_refused {
                            " pygame=zero_width_error"
                        } else {
                            ""
                        }
                    );
                    println!("{line}");
                    failures.push(line);
                }
                Verdict::PinMismatch {
                    expected,
                    got_sha256,
                    got_class,
                } => {
                    let line = format!(
                        "PIN MISMATCH size={} index={} pinned class={} sha256={} but got class={} sha256={got_sha256}",
                        o.size,
                        o.index,
                        expected.class.as_str(),
                        expected.sha256,
                        got_class.map_or("exact", DiffClass::as_str),
                    );
                    println!("{line}");
                    failures.push(line);
                }
            }
        }
    }
    failures
}

#[test]
fn render_matches_pygame_at_all_30_sizes() {
    let known = known_differences();
    let outcomes = judge(None, &known);
    let failures = report(&outcomes);
    let listed: BTreeSet<_> = outcomes.iter().map(|o| (o.size, o.index)).collect();
    for key in known.keys() {
        assert!(
            listed.contains(key),
            "known difference {key:?} is not a corpus entry"
        );
    }
    assert!(
        failures.is_empty(),
        "{} entries differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn pinned_difference_hash_mismatch_fails() {
    let pin = KnownDifference {
        size: 14,
        index: 3,
        class: DiffClass::Raster,
        sha256: "00".repeat(32),
    };
    let v = classify::verdict(false, || DiffClass::Raster, Some(&pin), &"11".repeat(32));
    assert!(!v.passes());
    assert!(
        matches!(v, Verdict::PinMismatch { ref expected, .. } if expected.size == 14 && expected.index == 3)
    );
    let ok = classify::verdict(false, || DiffClass::Raster, Some(&pin), &"00".repeat(32));
    assert_eq!(ok, Verdict::Pinned);
    let wrong_class = classify::verdict(false, || DiffClass::Shaping, Some(&pin), &"00".repeat(32));
    assert!(!wrong_class.passes());
    let stale = classify::verdict(true, || DiffClass::Raster, Some(&pin), &"00".repeat(32));
    assert!(!stale.passes(), "a pin on an exact entry fails");
    assert_eq!(
        classify::verdict(true, || unreachable!(), None, "x"),
        Verdict::Exact
    );

    // A real render: its hash pinned with one byte changed fails.
    let face = face();
    let s = text::render(face, 14, "&&", colour());
    let sha = output_sha256(&s);
    let mut bad = sha.clone().into_bytes();
    bad[0] = if bad[0] == b'0' { b'1' } else { b'0' };
    let pin = KnownDifference {
        size: 14,
        index: 2,
        class: DiffClass::Raster,
        sha256: String::from_utf8(bad).unwrap(),
    };
    assert!(!classify::verdict(false, || DiffClass::Raster, Some(&pin), &sha).passes());
}

#[test]
fn approved_differences_entries_hold_exactly_four_fields() {
    let raw: serde_json::Value =
        serde_json::from_slice(&read("golden/text/approved_differences.json")).expect("json");
    for entry in raw.as_array().expect("a list") {
        let keys: BTreeSet<&str> = entry
            .as_object()
            .expect("an object")
            .keys()
            .map(String::as_str)
            .collect();
        assert_eq!(keys, BTreeSet::from(["class", "index", "sha256", "size"]));
    }
    let extra = r#"[{"size":14,"index":1,"class":"raster","sha256":"00","note":"x"}]"#;
    assert!(serde_json::from_str::<Vec<KnownDifference>>(extra).is_err());
    let _ = known_differences();
}

#[test]
fn zero_width_text_is_refused_like_pygame() {
    let face = face();
    let colour = colour();
    let mut refused = 0;
    for e in corpus() {
        let r = text::try_render(face, e.size, &e.text, colour);
        if e.render == ZERO_WIDTH {
            refused += 1;
            assert_eq!(
                r,
                Err(TextError::ZeroWidth),
                "size {} index {}",
                e.size,
                e.index
            );
            let s = text::render(face, e.size, &e.text, colour);
            assert_eq!(
                (s.width() as i32, s.height() as i32),
                text::measure(face, e.size, &e.text)
            );
            assert_eq!(s.width(), 0);
        } else {
            let s = r.unwrap_or_else(|err| panic!("size {} index {}: {err}", e.size, e.index));
            assert_eq!(s, text::render(face, e.size, &e.text, colour));
        }
    }
    println!("pygame refused {refused} entries; try_render refuses the same");
    // A zero-advance glyph inside a string takes no room.
    assert_eq!(text::measure(face, 14, "a\u{ad}b"), (16, 19));
    assert_eq!(
        text::try_render(face, 14, "", colour).map(|s| (s.width(), s.height())),
        Ok((0, 19))
    );
    assert_eq!(
        text::try_render(face, 9, "A", colour),
        Err(TextError::UnknownSize(9))
    );
    assert!(matches!(
        text::try_render(face, 12, "a", colour),
        Err(TextError::MissingGlyph { size: 12, .. })
    ));
}

// --- E5: overlap rule -----------------------------------------------------

#[test]
fn overlap_rule_recorded_and_unique() {
    let face = face();
    let recorded = face.overlap_rule();
    assert!(
        ["max", "over", "or", "no-overlap-observed"].contains(&recorded),
        "overlap_rule {recorded:?}"
    );
    let known = known_differences();
    let pinned = |o: &Outcome| known.contains_key(&(o.size, o.index));
    let rule_of = |name: &str| OverlapRule::ALL.into_iter().find(|r| r.as_str() == name);
    let overlap_strings: BTreeSet<(u32, usize)> = corpus()
        .iter()
        .filter(|e| e.category == "overhang" || e.category == "calt" || e.category == "random")
        .map(|e| (e.size, e.index))
        .collect();

    let mut outputs: BTreeMap<&str, Vec<Outcome>> = BTreeMap::new();
    for rule in OverlapRule::ALL {
        outputs.insert(rule.as_str(), judge(Some(rule), &BTreeMap::new()));
    }
    let differing = |name: &str| -> Vec<(u32, usize, usize)> {
        outputs[name]
            .iter()
            .filter(|o| !pinned(o) && !o.pygame_refused && o.verdict != Verdict::Exact)
            .map(|o| (o.size, o.index, o.pixels))
            .collect()
    };
    for rule in OverlapRule::ALL {
        let d = differing(rule.as_str());
        println!(
            "overlap rule {}: {} unpinned entries differ, {} pixels",
            rule.as_str(),
            d.len(),
            d.iter().map(|x| x.2).sum::<usize>()
        );
    }
    match rule_of(recorded) {
        Some(rule) => {
            let d = differing(rule.as_str());
            assert!(
                d.iter().all(|x| x.2 == 0) && d.is_empty(),
                "recorded rule differs: {d:?}"
            );
            for other in OverlapRule::ALL.into_iter().filter(|r| *r != rule) {
                let hits = differing(other.as_str())
                    .into_iter()
                    .filter(|(s, i, px)| *px > 0 && overlap_strings.contains(&(*s, *i)))
                    .count();
                assert!(
                    hits >= 1,
                    "rule {} is not told apart from {}",
                    other.as_str(),
                    recorded
                );
            }
        }
        None => {
            let base = &outputs["max"];
            for rule in ["over", "or"] {
                for (a, b) in base.iter().zip(&outputs[rule]) {
                    assert_eq!(a.sha256, b.sha256, "size {} index {}", a.size, a.index);
                }
            }
            assert!(differing("max").is_empty());
        }
    }
}

// --- E6: loading ----------------------------------------------------------

fn atlas_json_with(edit: impl FnOnce(&mut serde_json::Value)) -> Vec<u8> {
    let mut doc: serde_json::Value =
        serde_json::from_slice(&read(&format!("{ATLAS}/atlas.json"))).expect("atlas.json");
    edit(&mut doc);
    serde_json::to_vec(&doc).expect("json")
}

#[test]
fn from_baked_rejects_format_1() {
    let json = atlas_json_with(|d| d["format"] = 1.into());
    let err = FontFace::from_baked(font_bytes(), &json, &atlas_pages()).unwrap_err();
    assert_eq!(err, TextError::UnsupportedFormat(1));
    let minimal = br#"{"format": 1, "sizes": {}}"#;
    let err = FontFace::from_baked(font_bytes(), minimal, &BTreeMap::new()).unwrap_err();
    assert_eq!(err, TextError::UnsupportedFormat(1));
}

#[test]
fn from_baked_accepts_each_overlap_rule() {
    let pages = atlas_pages();
    for rule in ["max", "over", "or", "no-overlap-observed"] {
        let json = atlas_json_with(|d| d["overlap_rule"] = rule.into());
        let face = FontFace::from_baked(font_bytes(), &json, &pages)
            .unwrap_or_else(|e| panic!("{rule}: {e}"));
        assert_eq!(face.overlap_rule(), rule);
        assert_eq!(face.sizes(), (10..40).collect::<Vec<u32>>());
    }
    let json = atlas_json_with(|d| d["overlap_rule"] = "undetermined".into());
    assert_eq!(
        FontFace::from_baked(font_bytes(), &json, &pages).unwrap_err(),
        TextError::UnknownOverlapRule("undetermined".into())
    );
    let mut missing = pages.clone();
    missing.remove("atlas-20.png");
    assert_eq!(
        FontFace::from_baked(
            font_bytes(),
            &read(&format!("{ATLAS}/atlas.json")),
            &missing
        )
        .unwrap_err(),
        TextError::MissingPage("atlas-20.png".into())
    );
}

/// Loads an externally baked atlas: `BANQUO_CANVAS_ATLAS_DIR` names a folder
/// holding `jetbrains-mono-regular/atlas.json` (or the atlas folder itself),
/// baked from the same font.
#[test]
#[ignore = "needs BANQUO_CANVAS_ATLAS_DIR"]
fn from_baked_reads_external_atlas() {
    let dir = PathBuf::from(
        std::env::var_os("BANQUO_CANVAS_ATLAS_DIR").expect("set BANQUO_CANVAS_ATLAS_DIR"),
    );
    let dir = if dir.join("atlas.json").is_file() {
        dir
    } else {
        dir.join("jetbrains-mono-regular")
    };
    let face =
        FontFace::from_dir(font_bytes(), &dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
    assert_eq!(face.sizes(), (10..40).collect::<Vec<u32>>());
    assert_eq!(face.atlas_font_sha256(), FONT_SHA256);
    for size in face.sizes() {
        println!(
            "external atlas size {size}: {} glyphs, advance {}, line height {}",
            face.glyph_count(size),
            face.advance(size).unwrap(),
            face.line_height(size).unwrap()
        );
    }
    println!(
        "external atlas: {} sizes, overlap_rule {}",
        face.sizes().len(),
        face.overlap_rule()
    );
    // Same font, same bake model: the external atlas renders the fixture's
    // subset string identically at every size.
    let fixture = self::face();
    let colour = colour();
    for size in 10..40 {
        let s = "ABCXYZ'";
        assert_eq!(
            text::render(&face, size, s, colour),
            text::render(fixture, size, s, colour),
            "size {size}"
        );
    }
}
